const cfg=$('跑团知识库配置').first().json;
const result=$input.first().json;
if(result.status!=='ok'||!Array.isArray(result.result?.points))throw new Error('本地知识库检索失败');
const hits=result.result.points;
return [{json:{rollSeed:Math.floor(Math.random()*4294967296),chatInput:cfg.chatInput,sessionId:cfg.sessionId,ragMatches:hits.map(h=>({id:h.payload.sourceId,title:h.payload.title,score:Number(h.score.toFixed(4))})),ragContext:hits.length?hits.map(h=>'['+h.payload.sourceId+'] '+h.payload.title+'\n'+h.payload.text).join('\n\n'):'未检索到达到相似度阈值的资料。'}}];

