const text = String(query ?? '').trim().toLowerCase().replace(/\s+/g, '');
const match = /^(\d{0,2})d(\d{1,4})([+-]\d{1,4})?$/.exec(text);
if (!match) return JSON.stringify({error:'格式应为 1d20、2d6+3 或 1d100，不能包含其他文字'});
const count = Number(match[1] || 1), sides = Number(match[2]), modifier = Number(match[3] || 0);
if (count < 1 || count > 50 || sides < 2 || sides > 1000 || Math.abs(modifier) > 1000) return JSON.stringify({error:'限制：1至50颗骰子，2至1000面，修正值绝对值不超过1000'});
const seed=$('向量相似度检索').first().json.rollSeed;
let state=seed>>>0;
for(let i=0;i<text.length;i++){state=Math.imul(state^text.charCodeAt(i),16777619)>>>0;}
function random(){state+=0x6D2B79F5;let t=state;t=Math.imul(t^(t>>>15),t|1);t^=t+Math.imul(t^(t>>>7),t|61);return ((t^(t>>>14))>>>0)/4294967296;}
const rolls = Array.from({length:count}, () => Math.floor(random()*sides)+1);
return JSON.stringify({expression:text,rolls,modifier,total:rolls.reduce((sum,value)=>sum+value,0)+modifier});
